def investigate(context, acquire):
    hist = acquire("history")

    def simulate(put_mode, trigger, channel_mode, actions):
        committed = {}
        work = {"main": {}, "other": {}}
        tx = {"main": False, "other": False}
        total = {"main": 0, "other": 0}
        last_changes = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if conn not in ("main", "other"):
                return None
            if op == "begin":
                if tx[conn]:
                    return None
                tx[conn] = True
                work[conn] = dict(committed)
            elif op == "commit":
                if not tx[conn]:
                    return None
                committed = dict(work[conn])
                tx[conn] = False
                other = "other" if conn == "main" else "main"
                if not tx[other]:
                    work[other] = dict(committed)
            elif op == "rollback":
                if not tx[conn]:
                    return None
                tx[conn] = False
                work[conn] = dict(committed)
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                if not isinstance(key, str) or not key:
                    return None
                if op == "delete":
                    if key in work[conn]:
                        del work[conn][key]
                        total[conn] += 1
                        if conn == "main":
                            last_changes = 1
                    else:
                        if conn == "main":
                            last_changes = 0
                else:
                    value = act.get("value")
                    if not isinstance(value, int) or value < 0 or value > 1000000:
                        return None
                    existed = key in work[conn]
                    if op == "put":
                        if put_mode == "ignore":
                            if existed:
                                if conn == "main":
                                    last_changes = 0
                                continue
                            work[conn][key] = value
                            total[conn] += 1
                            if conn == "main":
                                last_changes = 1
                            if trigger:
                                total[conn] += 1
                                if conn == "main":
                                    last_changes += 1
                        elif put_mode == "replace":
                            work[conn][key] = value
                            total[conn] += 1
                            if conn == "main":
                                last_changes = 1
                            if trigger:
                                total[conn] += 1
                                if conn == "main":
                                    last_changes += 1
                        elif put_mode == "upsert":
                            if existed:
                                work[conn][key] = value
                                total[conn] += 1
                                if conn == "main":
                                    last_changes = 1
                            else:
                                work[conn][key] = value
                                total[conn] += 1
                                if conn == "main":
                                    last_changes = 1
                                if trigger:
                                    total[conn] += 1
                                    if conn == "main":
                                        last_changes += 1
                    elif op == "update":
                        if existed:
                            work[conn][key] = value
                            total[conn] += 1
                            if conn == "main":
                                last_changes = 1
                        else:
                            if conn == "main":
                                last_changes = 0
            else:
                return None

        if channel_mode == "changes":
            ch = last_changes
        elif channel_mode == "total_main":
            ch = total["main"]
        elif channel_mode == "total_both":
            ch = total["main"] + total["other"]
        else:
            return None
        return (ch, len(committed), sum(committed.values()))

    put_modes = ["ignore", "replace", "upsert"]
    triggers = [False, True]
    channel_modes = ["changes", "total_main", "total_both"]

    survivors = []
    for pm in put_modes:
        for tr in triggers:
            for cm in channel_modes:
                ok = True
                for rec in hist:
                    actions = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    res = simulate(pm, tr, cm, actions)
                    if res is None:
                        ok = False
                        break
                    ch, cc, cs = res
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    survivors.append((pm, tr, cm))

    if not survivors:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for pm, tr, cm in survivors:
        res = simulate(pm, tr, cm, actions)
        if res is None:
            return {"value": None, "unresolved": True}
        ch, cc, cs = res
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cc)
        elif goal == "committed_sum":
            results.append(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}
